  ts.eval('\nLocals.TestStandCfg = RunState.Engine.GetTestStandPath(TestStandPath_Config)');
  ts.eval('\nLocals.TestStandGlobalCfg = RunState.Engine.GetTestStandPath(TestStandPath_GlobalConfig)');
